import{esc,button,input,select}from'../phase4/ui.js';
import * as V from './b17-view.js';
import{groups,inner,fmt,value,mul}from'./b18-model.js';
const f=(k,l,v)=>input(k,l,v,'autocomplete="off" spellcheck="false"'),btn=(a,l,d='')=>button('b18-'+a,l,d),on=b=>`aria-pressed="${!!b}"`,colors=['#ca9663','#74a69c','#a798bf','#c6b16a','#9eac75','#7ba1b3'];
const guesses=[['negative','比0小'],['zero','等于0'],['part','0与1之间'],['one','等于1'],['more','比1大']];
const story=(m)=>`<label class="b18-story field">用自己的故事说一说<textarea id="b18-story-input" data-xfield="story" maxlength="800" rows="2" placeholder="有什么东西？要分给谁，或装成多大的份？">${esc(m.story)}</textarea><small>故事会保存下来，含义留给你继续说明。</small></label>`;
const rewrite=s=>s.replaceAll('data-xfield="','data-xfield="work.').replaceAll('data-x="b17-','data-x="b18-op-');
export const quantity=(r,unit)=>unit==='元'&&Number.isSafeInteger(r[0]*100/r[1])?(r[0]/r[1]).toFixed(2):fmt(r);
function decomposition(t,m){const b=m.board,p=groups(t,b);let cursor=0;return`<p class="b18-caption">原来的量：${t.n}/${t.d}　·　每小块都是 1/${t.d}</p><div class="b18-decompose">${p.map((n,g)=>`<div class="b18-group" style="--color:${colors[g%colors.length]}">${Array.from({length:n},()=>{const i=++cursor;return`<span class="b18-little" style="--piece:${520/Math.max(t.n,8)}px"></span>${i<t.n?btn('cut',b.cuts.includes(i)?'接':'分',`data-index="${i}" ${on(b.cuts.includes(i))} aria-label="第${i}小份后${b.cuts.includes(i)?'接起来':'分一组'}"`):''}`;}).join('')}</div>`).join('')}</div><p class="b18-caption">${p.map(n=>`${n} 小份`).join(' ＋ ')}</p><div class="b18-saved">${b.saved.map(x=>`<span>${esc(x.equation)}</span>`).join('')}</div>`;}
function trades(t,m){const b=m.board;if(!b.started)return`<div class="b18-big">${t.a[0]} 又 ${t.a[1]}/${t.d}　${t.op==='+'?'＋':'−'}　${t.b[0]} 又 ${t.b[1]}/${t.d}</div>`;return`<p class="b18-caption">同一大小的整体　·　每个小份是 1/${t.d}</p><div class="b18-wholes">${Array.from({length:b.w},(_,i)=>`<div class="b18-one" aria-label="整体${i+1}">1</div>`).join('')}</div><div class="b18-loose">${Array.from({length:b.p},(_,i)=>`<span class="b18-piece">1/${t.d}</span>`).join('')}</div><p class="b18-caption">现在有 ${b.w} 个整体和 ${b.p} 个小份${t.op==='-'?`　·　已拿走 ${b.takenW}/${t.b[0]} 个整体、${b.takenP}/${t.b[1]} 个小份`:''}</p>`;}
function sharing(t,m){const b=m.board,d=t.d*(b.factor||1);return`<p class="b18-caption">整条表示 1${t.unit||'个整体'}；有颜色的部分是原来要分的 ${t.n}/${t.d}</p><div class="b18-sharebar" style="--d:${d}">${Array.from({length:d},(_,i)=>{const owner=b.owners[i]??-1,filled=i<t.n*(b.factor||1);return`<i style="background:${filled?(owner<0?'#dcb689':colors[owner%colors.length]):'#f9f3e9'};border-right-width:${(i+1)%(b.factor||1)===0?3:1}px"></i>`;}).join('')}</div>${b.factor?`<p class="b18-caption">每小块是原来整个的 1/${d}；选一个人，再点小块分给他。</p><div class="b18-people">${Array.from({length:t.people},(_,i)=>btn('person',`第${i+1}人 · ${b.owners.filter(x=>x===i).length}小块`,`data-index="${i}" ${on(b.selected===i)} style="--color:${colors[i%colors.length]}"`)).join('')}</div><div class="b18-loose">${b.owners.map((owner,i)=>btn('give',owner<0?'待分':`第${owner+1}人`,`data-index="${i}" aria-label="分配第${i+1}小块" style="background:${owner<0?'#f2dfc2':colors[owner%colors.length]};color:#302c24"`)).join('')}</div>`:''}`;}
function scaling(t,m){const b=m.board,st=t.stages[b.index],q=r=>quantity(r,t.unit);if(!st)return`<div class="b18-saved">${b.records.map((r,i)=>`<p>${i+1}. ${esc(t.stages[i].label)}<br>${q(r.before)} → ${q(value(r.result))} ${esc(t.unit||'')}</p>`).join('')}</div>`;const r=value(st.ratio),wholes=Math.ceil(r[0]/r[1]);return`<p class="b18-caption">${b.index+1}/${t.stages.length}　${esc(st.label)}</p><div class="b18-big">这一轮的整个：${q(b.current)} ${esc(t.unit||'')}</div>${b.denom?`<div class="b18-scale-wrap" style="--wholes:${wholes}">${Array.from({length:wholes},(_,w)=>`<div class="b18-scale-whole" style="--d:${b.denom}">${Array.from({length:b.denom},(_,i)=>{const n=w*b.denom+i;return btn('piece',b.selected.includes(n)?'●':'',`data-index="${n}" ${on(b.selected.includes(n))} aria-label="取第${n+1}小份"`);}).join('')}</div>`).join('')}</div><p class="b18-caption">每个框仍表示这一轮的整个；已取 ${b.selected.length} 个小份。</p>`:'<p class="b18-caption">先选择怎样等分这个整体，再取出需要的份。</p>'}${b.records.length?`<p class="b18-prior">上一轮：${q(b.records.at(-1).before)} → ${q(value(b.records.at(-1).result))}。这一轮以新的量为整体。</p>`:''}`;}
function area(t,m){const b=m.work.board,[a,c]=b.forms,cols=Math.ceil(a[0]/a[1])*a[1],rows=Math.ceil(c[0]/c[1])*c[1],u=Math.min(210,300/Math.ceil(c[0]/c[1]),500/Math.ceil(a[0]/a[1])),cw=u/a[1],rh=u/c[1];return`<div class="b18-area" style="width:${cols*cw+46}px"><div class="b18-cols" style="grid-template-columns:repeat(${cols},${cw}px)">${Array.from({length:cols},(_,i)=>btn('op-column','↓',`data-index="${i}" ${on(b.columns.includes(i))} aria-label="取第${i+1}列"`)).join('')}</div><div class="b18-area-main"><div class="b18-rows" style="grid-template-rows:repeat(${rows},${rh}px)">${Array.from({length:rows},(_,i)=>btn('op-row','→',`data-index="${i}" ${on(b.rows.includes(i))} aria-label="取第${i+1}行"`)).join('')}</div><div class="b18-area-grid" style="grid-template-columns:repeat(${cols},${cw}px);grid-template-rows:repeat(${rows},${rh}px)">${Array.from({length:rows*cols},(_,i)=>`<i style="background:${b.rows.includes(Math.floor(i/cols))&&b.columns.includes(i%cols)?'#c98d55':b.rows.includes(Math.floor(i/cols))?'#cce1d9':b.columns.includes(i%cols)?'#eddbbd':'#faf6ed'};border-right-width:${i%a[1]===a[1]-1?3:1}px;border-bottom-width:${Math.floor(i/cols)%c[1]===c[1]-1?3:1}px"></i>`).join('')}</div></div></div><p class="b18-caption">横向每小格长 1/${a[1]}，纵向高 1/${c[1]}。粗线围成的正方形面积是 1。<br>小格等面积，不一定是正方形；两种颜色重合的部分就是取出的面积。</p>`;}
export function visual(t,m){const b=m.board;switch(t.type){case'x-fracdecompose':return decomposition(t,m);case'x-mixedtrade':return trades(t,m);case'x-fracshare':return sharing(t,m);case'x-scalechain':return scaling(t,m);case'x-fractioncase':if(!b.started)return`<div class="b18-big">${esc(t.scene||'先想一想，这两个量该怎样连接。')}</div>${t.estimate?'<p class="b18-caption">可以借 0、1/2、1 和附近的整份来估计。</p>':''}`;return(t.op==='*'&&m.work.board.forms?area(t,m):rewrite(V.visual(inner(t),m.work)))+(b.estimate?`<p class="b18-prior">最初估计：${esc(b.estimate[0])} 到 ${esc(b.estimate[1])}；算完再回看。</p>`:'')+(b.normalized?`<p class="b18-caption">两边同乘 ${esc(b.normalized.factor)}：${esc(t.a)} ÷ ${esc(t.b)} → ${esc(b.normalized.a)} ÷ 1</p>`:'');}}
export function controls(t,m){const b=m.board;switch(t.type){
 case'x-fracdecompose':return f('equation','按现在的分组写一个加法等式',m.equation)+btn('save','留下这一种分法')+btn('new-groups','换一种分组');
 case'x-mixedtrade':if(!b.started)return f('guess','先估一估，结果大约多少',m.guess)+btn('start','摆出来看看');return btn('split','换开一个整体',b.w?'':'disabled')+btn('merge',`把 ${t.d} 小份合成一个整体`,b.p>=t.d?'':'disabled')+btn('all-pieces','全部换成小份',b.w?'':'disabled')+(t.op==='-'?btn('take-whole','拿走一个整体',b.takenW<t.b[0]?'':'disabled')+btn('take-part','拿走一个小份',b.takenP<t.b[1]?'':'disabled'):'')+f('whole','剩下几个完整的整体',m.whole)+f('part','不足一个整体的部分是多少',m.part)+f('answer','总量写成一个分数或带分数',m.answer);
 case'x-fracshare':if(!b.started)return f('guess','每人会得到多少，先猜一猜',m.guess)+(t.story?story(m):'')+btn('start','开始分');return f('factor','原来每一份再平均切成几小块',m.factor)+btn('cut','按这个办法切')+(b.factor?f('answer','每人拿到原来整个的几分之几',m.answer)+f('equation','每人的量 × 人数 = 原来的量',m.equation):'')+(t.story?story(m):'');
 case'x-scalechain':{const st=t.stages[b.index];if(!st)return'';return f('denom','这一轮的整个，平均分成几份',m.denom)+btn('cut','分好，再点着取')+(b.denom?f('unit','这一小份有多少',m.unit)+f('amount','图中取出的量有多少',m.amount)+(st.decimal?f('decimal',`把 ${st.percent}% 写成小数倍数`,m.decimal):'')+f('result',st.mode==='off'?'拿走折扣后，还剩多少':st.mode==='add'?'加上这部分后，一共多少':'这一轮得到多少',m.result)+btn('commit',b.index===t.stages.length-1?'留下这次结果':'用这个结果继续下一步'):'');}
 case'x-fractioncase':if(!b.started)return select('choice','先选这次的动作',m.choice,[['+','接起两个量'],['-','从第一个量拿走第二个量'],['*','按第二个量的倍数取第一份'],['/','看第一个量能装下几组第二个量']])+(t.estimate?f('low','估计至少多少',m.low)+f('high','估计最多多少',m.high):select('guess','先猜结果在哪里',m.guess,guesses))+(t.story?story(m):'')+btn('start','把想法摆出来');
  {const w=m.work.board,ready=w.forms&&(t.op==='*'?w.columns.length===w.forms[0][0]&&w.rows.length===w.forms[1][0]:t.op==='/'?w.rest:w.combined);return rewrite(V.controls(inner(t),m.work))+(ready?`<div class="b18-record"><p>把这次发现留下来</p>${t.estimate?select('inside','实际结果在最初估计的范围里吗',m.inside,[['yes','在范围里'],['no','不在，原来的估计需要调整']]):''}${t.simple?f('simple','合到最简后的分数',m.simple):''}${t.mixed?f('whole','其中有几个完整的1',m.whole)+f('part','剩下不足1的部分是多少',m.part):''}${t.tile?f('tile','每一个小格占1平方单位的多少',m.tile)+f('count','重合的区域共有几个小格',m.count):''}${t.inverse?f('equation','几组 × 每组的量 = 原来的量',m.equation):''}${t.reciprocal?f('inverse','两边一起乘什么，让每组的量变成1',m.inverse)+f('scaledA','前面的量一起变成多少',m.scaledA)+f('scaledB','每组的量变成多少',m.scaledB)+btn('normalize','一起改变，比较组数'):''}${t.story?story(m):''}</div>`:'');}
 }return'';}
export const render=(t,m)=>`<section class="b18-work b17-work"><div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}${m.issue?`<p class="b18-issue" role="status">${esc(m.issue)}</p>`:''}${btn('reset','重新摆，保留之前的尝试')}</div></section>`;
